Method.Implementation:
	Set tCredential=##class(Ens.Config.Credentials).%OpenId(..Credentials)
	Set tUsername=tCredential.Username
	Set tPassword=tCredential.Password
	set tFilename=..TargetFileName
	set MaxRetry = (..FailureTimeout/..RetryInterval)+1
	Set updatedSuccessEmailSubject = ..replaceWithParticularFormat(..SuccessEmailSubject)
	Set updatedFailureEmailSubject = ..replaceWithParticularFormat(..FailureEmailSubject)
	Set updatedSuccessEmailbody = ..replaceWithParticularFormat(..SucessEmailBody)
	Set updatedFailureEmailbody = ..replaceWithParticularFormat(..FailureEmailBody)

	Quit:'$IsObject(pRequest.Stream) $$$ERROR($$$EnsErrGeneral,"No Stream contained in StreamContainer Request")
	If "@"'=$E(..Adapter.FilePath) {
		Set tFilename=..Adapter.CreateFilename(##class(%File).GetFilename(pRequest.OriginalFilename),tFilename)
		Set tSC=..Adapter.PutStream(tFilename, pRequest.Stream)
		Do pRequest.%Save() ; re-save in case PutStream() optimization changed the Stream filename
	} Else {
		#; Forward to agent
		If pRequest.Stream.%Extends("%Library.FileStreamAdaptor") {
			#; copy to a global stream in a new container
			Set tStream=##class(%FileBinaryStream).%New()
			Merge tStream.Attributes=pRequest.Stream.Attributes
			Set tSC=tStream.CopyFrom(pRequest.Stream)
			Set tSC=tStream.SaveStream()  Quit:$$$ISERR(tSC) tSC
			Set tMsg=##class(Ens.StreamContainer).%New(tStream)
		} Else {
			Set tMsg=pRequest
		}
		Set tFilename=##class(Ens.Util.File).CreateTimestamp(##class(%File).GetFilename(pRequest.OriginalFilename),tFilename)
		Set tAgent=$P(..Adapter.FilePath,":"), tTimeout=+$P(tAgent,"(",2), tAgent=$P(tAgent,"(")  Set:'tTimeout tTimeout=-1
		Set tSC=..EnQueueToService(tAgent,tMsg,..%RequestHeader,,tFilename) ; !!! Sync(...,,tTimeout,..%RequestHeader.Description)
	}
	if $$$ISOK(tSC) {
	#; Lftp the file to the target directory
		set fullFileNm=..Adapter.FilePath_"/" _tFilename
		Set tCMD = ##class(Ens.Util.FunctionSet).replace(..LftpCmd,"%1",..Host)
		Set tCMD = ##class(Ens.Util.FunctionSet).replace(tCMD,"%2",tUsername)
		Set tCMD = ##class(Ens.Util.FunctionSet).replace(tCMD,"%3",tPassword)
		Set tCMD = ##class(Ens.Util.FunctionSet).replace(tCMD,"%4",..Adapter.FilePath)
		Set tCMD = ##class(Ens.Util.FunctionSet).replace(tCMD,"%5",tFilename)
		Set tCMD = ##class(Ens.Util.FunctionSet).replace(tCMD,"%6",..TargetFilePath)
		$$$TRACE("Lftp file: " _ tFilename)
		Set tStatus= ##class(IHC.ITF.ITFCOMMON.Utility).ExecuteShellCmd(tCMD, ..STDOUT, ..STDERR) 
        if tStatus=0 {
	       If ..SuccessEmailSubject '= "" 
		   {
			 $$$TRACE("Sending alert for successful file transfer.")
			 do ..ItfSendEmailOnSuccess(updatedSuccessEmailSubject, updatedSuccessEmailbody)
		   }
		   Else 
		   {
		 	 $$$TRACE("No SuccessEmailSubject found; email will not be sent.")
		   }

		   If ##class(%File).Exists(fullFileNm) {
		 	 $$$TRACE("Delete File: " _ fullFileNm )
			 Set tSC = ##class(%File).Delete(fullFileNm)
		   }
		   else {
		     Set tSC=$$$ERROR($$$GeneralError,"Unable to execute command: "_tCMD) 
		   }
        }
        else
	    {		
		  If ..FailureEmailSubject '= "" 
		  {
			$$$TRACE(MaxRetry_"  Retry Count inside else part : "_..RetryCount)
			$$$TRACE("Sending alert for failure in file transfer.")
			do ..valueToBeReplaced.SetAt(tSC,"%EM")
			Set updatedFailureEmailSubject = ..replaceWithParticularFormat(updatedFailureEmailSubject)
			Set updatedFailureEmailbody = ..replaceWithParticularFormat(updatedFailureEmailbody)
			do ..ItfSendEmailOnError(updatedFailureEmailSubject, updatedFailureEmailbody)
		  }
		  Else 
		  {
			$$$TRACE("No FailureEmailSubject found; email will not be sent.")
		  }
	    }

	 }
	 else {
        Set tSC=$$$ERROR($$$GeneralError,"Unable to Save data to the file path. "_..Adapter.FilePath) 
	 }

	Quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("FilePath",.tValue) {
	If "@"=$E(tValue) {
		Set tAgent=$E($P(tValue,":"),2,*)
		#; if agent package is installed, call it to find the appropriate agent Service connection.
		try {
			Set tSC=$classmethod("EnsLib.Agent.Interface","GetAgentService",tAgent,pItem.Name,.tAgentService)
			Set:""'=tAgentService&&$$$ISOK(tSC) pArray(tAgentService)=""
		} catch {  }
	}
}
